  for k in ['d_model','num_layers','num_heads','d_ff']:
   v=re.search(r'- '+k+r': (\d+)',m[2])
   if v:d[k]=int(v[1])
  for k,p in [('lr',r'- Learning rate: ([\deE.+-]+)'),('opt',r'- Optimizer: (\w+)')]:
   v=re.search(p,m[2])
   if v:d[k]=float(v[1]) if k=='lr' else v[1]
  out.append(d)
 return out
for mode in ['wider_smallerFF','narrower_deeper']:
 def match(a,b):
  if a['num_heads']!=b['num_heads']:return False
  if mode=='wider_smallerFF':return a['d_model']>b['d_model'] and a['d_ff']<b['d_ff'] and a['num_layers']<=b['num_layers']
  return a['d_model']<b['d_model'] and a['num_layers']>b['num_layers']
 hist=[]
 for r in h:
  if r['family']!='bigram_lm':continue
  ans=re.findall('[A-E]',r['answer'])
  for a,b in itertools.permutations(parse(r),2):
   if not all(k in a and k in b for k in ['d_model','num_layers','num_heads','d_ff','lr','opt']):continue
   if a['opt']!=b['opt'] or a['opt'] not in ['Adam','AdamW'] or a['lr']!=b['lr'] or a['lr']<.001 or not match(a,b):continue
