 res=collections.defaultdict(list)
 for rows in groups.values():
  for a,b in itertools.permutations(rows,2):
   if a['optimizer']!=b['optimizer'] or a['optimizer']['type'] not in ['Adam','AdamW'] or not match(a,b):continue
